// 3D model of the right orbit from Z-Anatomy meshes (CC BY-SA 4.0, based on
// BodyParts3D): the orbital bones, the globe, the extraocular muscles and the
// common tendinous ring, the lacrimal apparatus, nerves II, III, IV, VI and
// V1, and the ophthalmic artery and veins. The nasociliary and lacrimal
// nerves, the ciliary ganglion and its roots and the short ciliary nerves are
// drawn for this app. Geometry and the traced courses live in
// data/orbit-meshes.js, generated by tools/export_zanatomy.py.
// Coordinates are centimetres centred in the orbit: +y = superior,
// +z = anterior, the patient's right side is -x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.orbit = {
  // Default view: from above and behind, front of the orbit at the top, tilted
  // to the right side, as at a superior (transcranial) approach.
  camera: { target: [0, 0, 0.2], radius: 18, theta: Math.PI - 0.45, phi: 0.62 },

  // [theta, phi] for the view buttons. "From above" has anterior at the top
  // (the patient's right on the right); "Front" faces the patient.
  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [Math.PI, 0.12],
    anterior: [0, Math.PI / 2]
  },
  viewLabels: { inferior: "From above", anterior: "Front" },

  // Starting axial level (0 = bottom of the model, 1 = top): through the optic nerve.
  sectionLevel: 0.45,

  look: {
    frontal: { kind: "bone", opacity: 0.45 },
    sphenoid: { kind: "bone", color: 0xe6d6b4, opacity: 0.6 },
    ethmoid: { kind: "bone", opacity: 0.5 },
    maxilla: { kind: "bone", opacity: 0.5 },
    zygomatic: { kind: "bone", opacity: 0.5 },
    lacrimal_bone: { kind: "bone", opacity: 0.6 },
    globe: { kind: "cartilage", color: 0xf2efe8, opacity: 0.55 },
    inner_eye: { kind: "gland", color: 0x7a90b8, opacity: 0.8 },
    tarsi: { kind: "cartilage", color: 0xd8cfc0 },
    lockwood: { kind: "cartilage", color: 0xc8c2d8, opacity: 0.3 },
    levator: { kind: "muscle", color: 0xb5524a },
    superior_rectus: { kind: "muscle", color: 0xa84640 },
    inferior_rectus: { kind: "muscle", color: 0xa84640 },
    medial_rectus: { kind: "muscle", color: 0x9a3c3c },
    lateral_rectus: { kind: "muscle", color: 0x9a3c3c },
    superior_oblique: { kind: "muscle", color: 0xb06058 },
    inferior_oblique: { kind: "muscle", color: 0xb06058 },
    annulus: { kind: "cartilage", color: 0xd8d0c0 },
    lacrimal_gland: { kind: "gland", color: 0xd9a46e },
    lacrimal_drainage: { kind: "duct", color: 0x8fc7d8 },
    cn2: { kind: "nerve", color: 0xf0d27a },
    cn3: { kind: "nerve" },
    cn4: { kind: "nerve" },
    cn6: { kind: "nerve" },
    v1: { kind: "nerve", color: 0xf2c94c },
    v2: { kind: "nerve", color: 0xf2c94c },
    nasociliary: { kind: "nerve" },
    lacrimal_nerve: { kind: "nerve" },
    ciliary_ganglion: { kind: "nerve", color: 0xe8a93a },
    ciliary_roots: { kind: "nerve" },
    short_ciliary: { kind: "nerve" },
    ophthalmic_artery: { kind: "artery" },
    ophthalmic_branches: { kind: "artery" },
    lacrimal_artery: { kind: "artery" },
    supraorbital_artery: { kind: "artery" },
    ethmoidal_arteries: { kind: "artery" },
    ica: { kind: "artery" },
    ophthalmic_veins: { kind: "vein" },
    cavernous_sinus: { kind: "vein", opacity: 0.5 }
  },

  build(THREE, h) {
    return h.fromMeshes("orbit", this.look);
  }
};
